	b := uniqueEntryName(used, "2026", "회의록", "md")
	if a == b {
		t.Fatalf("folders should keep them apart: %q %q", a, b)
	}
	if strings.Contains(b, "(2)") {
		t.Fatalf("a different folder is not a collision: %q", b)
	}
